function sendEnquiry(f,ev){
 const via=(ev&&ev.submitter||document.activeElement||{}).value==='email'?'email':'whatsapp';
 const d=new FormData(f),t=`Hi DEVOCRAT! I'm ${d.get('name')} (${d.get('phone')}).\nI want to build: ${d.get('kind')}.\n\n${d.get('msg')}`;
 if(via==='email')location.href='mailto:'+ENQUIRY_EMAIL+'?subject='+encodeURIComponent('New enquiry: '+d.get('kind')+' — '+d.get('name'))+'&body='+encodeURIComponent(t);
 else window.open('https://wa.me/'+ENQUIRY_WHATSAPP+'?text='+encodeURIComponent(t),'_blank','noopener');
 return false;
}
function toggleMenu(force){const n=view.querySelector('.worldnav');if(!n)return;const open=force===undefined?!n.classList.contains('menu-open'):force;n.classList.toggle('menu-open',open);document.body.classList.toggle('overlay-open',open);n.querySelector('.menubtn')?.setAttribute('aria-expanded',open)}
view.addEventListener('click',e=>{const a=e.target.closest('[data-go]');if(!a)return;e.preventDefault();toggleMenu(false);document.getElementById(a.dataset.go)?.scrollIntoView({behavior:'smooth',block:'start'})});
/* ===== Bilingual hover labels (desktop only): visitor's language, English on hover ===== */

const LABEL_EN=['All worlds','About','Services','Prototypes','Offers','Discuss','Meet the family','Send message'];
const LANG_KEY='devocrat-label-lang';
const desktopUI=()=>matchMedia('(hover: hover) and (pointer: fine)').matches;
const langByCode=c=>LANGS.find(l=>l.c===c);
// English, unknown, or a language with no usable labels → the Tamil default
function labelLang(code){const l=langByCode(code);return l&&l.l?l:langByCode('ta')}
let visitLang=null; // choice for this world visit when the visitor didn't ask us to remember it
function readLang(){try{return localStorage.getItem(LANG_KEY)}catch(_){return null}}
function saveLang(c){try{localStorage.setItem(LANG_KEY,c)}catch(_){}}
function applyLabels(){
 if(!desktopUI())return;const lang=labelLang(visitLang||readLang()||'ta');
 view.querySelectorAll('[data-k]').forEach(el=>{const k=+el.dataset.k,en=LABEL_EN[k],loc=lang.l[k];
  if(!el.dataset.en){el.dataset.en=el.textContent.trim();}
  el.classList.add('swap');el.setAttribute('aria-label',en);
  el.innerHTML=`<span class="sw-loc" lang="${lang.c}" dir="${lang.rtl?'rtl':'ltr'}">${loc}</span><span class="sw-en" lang="en">${k===6?'<span class="long">Meet the </span>family':en}</span>`;
 });
}
/* Rough location → language: nearest Indian state capital, or nearest country */
const STATE_PTS=[[13.08,80.27,'ta'],[11.66,78.15,'ta'],[9.93,78.12,'ta'],[8.52,76.94,'ml'],[10.85,76.27,'ml'],[12.97,77.59,'kn'],[15.35,75.14,'kn'],[17.39,78.49,'te'],[16.51,80.65,'te'],[14.68,77.6,'te'],[19.08,72.88,'mr'],[18.52,73.86,'mr'],[21.15,79.09,'mr'],[15.49,73.83,'kok'],[23.02,72.57,'gu'],[22.3,70.8,'gu'],[30.73,76.78,'pa'],[31.63,74.87,'pa'],[22.57,88.36,'bn'],[26.14,91.74,'as'],[20.3,85.82,'or'],[24.82,93.94,'mni'],[34.08,74.8,'ks'],[32.73,74.86,'doi'],[26.12,85.39,'mai'],[25.59,85.14,'hi'],[28.61,77.21,'hi'],[26.85,80.95,'hi'],[23.26,77.41,'hi'],[26.91,75.79,'hi'],[21.25,81.63,'hi'],[23.34,85.31,'hi'],[30.32,78.03,'hi'],[31.1,77.17,'hi'],[27.33,88.61,'ne'],[26.4,90.27,'brx']];
const COUNTRY_PTS=[[28.39,84.12,'ne'],[23.68,90.36,'bn'],[30.38,69.35,'ur'],[7.87,80.77,'si'],[15.87,100.99,'th'],[35.86,104.2,'zh'],[36.2,138.25,'ja'],[35.9,127.77,'ko'],[61.52,105.32,'ru'],[24.71,46.68,'ar'],[26.82,30.8,'ar'],[23.42,53.85,'ar'],[33.22,43.68,'ar'],[31.79,-7.09,'ar'],[40.46,-3.75,'es'],[23.63,-102.55,'es'],[-38.42,-63.62,'es'],[4.57,-74.3,'es'],[46.23,2.21,'fr'],[51.17,10.45,'de'],[47.52,14.55,'de'],[39.4,-8.22,'pt'],[-14.24,-51.93,'pt'],[41.87,12.57,'it'],[37.09,-95.71,'en'],[55.38,-3.44,'en'],[-25.27,133.78,'en'],[56.13,-106.35,'en']];
function nearest(lat,lon,pts){let b=null,bd=1e9;for(const [a,o,c] of pts){const d=(a-lat)**2+((o-lon)*Math.cos(lat*Math.PI/180))**2;if(d<bd){bd=d;b=c}}return b}
function langFromPosition(lat,lon){const inIndia=lat>6&&lat<37.5&&lon>68&&lon<97.5;return inIndia?nearest(lat,lon,STATE_PTS):nearest(lat,lon,COUNTRY_PTS)}
function askLanguage(done){
 const opts=LANGS.map(l=>`<option value="${l.c}">${l.nat}${l.nat!==l.n?' — '+l.n:''}</option>`).join('');
 const d=document.createElement('div');d.className='lang-dialog';d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');d.setAttribute('aria-labelledby','langTitle');
 d.innerHTML=`<div class="lang-card"><div class="lang-kicker">DEVOCRAT</div><h2 id="langTitle">A quick question before visiting</h2>
  <p>Which language do you speak? Choose from the list, or let us work it out from your location.</p>
  <label class="lang-field">Your language<select id="langPick">${opts}</select></label>
  <div class="lang-actions"><button type="button" class="lang-btn primary" data-act="ok">Continue</button><button type="button" class="lang-btn" data-act="geo">Use my location</button><button type="button" class="lang-btn ghost" data-act="cancel">Cancel</button></div>
  <label class="lang-remember"><input type="checkbox" id="langRemember"> Remember my choice</label>
  <p class="lang-status" aria-live="polite"></p>
  <p class="lang-note">Note: this is only for a button feature to work — the page language will not change.</p></div>`;
 document.body.appendChild(d);document.body.classList.add('overlay-open');
 const pick=d.querySelector('#langPick'),status=d.querySelector('.lang-status');
 try{const nav=(navigator.language||'').toLowerCase().split('-')[0];if(langByCode(nav))pick.value=nav}catch(_){}
 setTimeout(()=>pick.focus(),50);
 const finish=c=>{if(d.querySelector('#langRemember').checked)saveLang(c);visitLang=c;d.remove();document.body.classList.remove('overlay-open');done()};
 d.addEventListener('click',e=>{const a=e.target.closest('[data-act]')?.dataset.act;if(!a)return;
  if(a==='ok')finish(pick.value);
  else if(a==='cancel')finish('ta');
  else if(a==='geo'){if(!navigator.geolocation){status.textContent='Location is not available here — please pick from the list.';return}
   status.textContent='Finding your location…';
   navigator.geolocation.getCurrentPosition(p=>{const c=langFromPosition(p.coords.latitude,p.coords.longitude)||'ta';pick.value=c;status.textContent='We picked '+(langByCode(c)?.n||'Tamil')+' — press Continue, or change it.'},
    ()=>{status.textContent='Could not get your location — please pick from the list.'},{timeout:10000,maximumAge:600000})}});
 d.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();finish('ta')}});
}
function prepareLabels(){requestAnimationFrame(fitBrand);if(!desktopUI())return;visitLang=null;if(readLang()){applyLabels();fitBrand();return}askLanguage(()=>{applyLabels();fitBrand()})}

/* Show the tagline under the logo only when it clears the header links */
function fitBrand(){const n=view.querySelector('.worldnav');if(!n)return;const br=n.querySelector('.wbrand'),sm=br&&br.querySelector('small'),links=n.querySelector('.wlinks');if(!sm||!links)return;
 br.classList.remove('no-tag');if(getComputedStyle(links).display==='none'||getComputedStyle(sm).display==='none')return;
 const first=links.firstElementChild,last=links.lastElementChild,fam=n.querySelector('.familybtn');
 const clash=sm.getBoundingClientRect().left+sm.scrollWidth+16>first.getBoundingClientRect().left||(fam&&last.getBoundingClientRect().right+12>fam.getBoundingClientRect().left);
 br.classList.toggle('no-tag',clash)}
addEventListener('resize',fitBrand);document.fonts&&document.fonts.ready.then(fitBrand);

