// Each animated element carries data-s/data-e (its slice of the 0→1 scroll progress) and a class naming the effect.
const SC=(type,s,e)=>` class="sc-${type}" data-s="${s}" data-e="${e}"`+(type==='draw'?' pathLength="1"':'');
const LIVE=s=>` class="sc-live" data-on="${s}"`;
// spread n items over [s,e], each lasting w
const stg=(i,n,s,e,w)=>{const a=n>1?s+(e-s-w)*i/(n-1):s;return [+a.toFixed(3),+(a+w).toFixed(3)]};
