function scrollScene(id){const c=SCROLL_COPY[id]||SCROLL_COPY.modern,svg=(SCENES[id]||SCENES.modern)();
 return `<section class="scrolly" data-world="${id}" aria-label="${c.title}"><div class="sc-sticky">
  <div class="sc-stage"><svg viewBox="0 0 1200 700" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${c.title}">${svg}</svg></div></div></section>`}

const easeSc={out:t=>1-Math.pow(1-t,3),back:t=>{const c1=1.70158,c3=c1+1;return 1+c3*Math.pow(t-1,3)+c1*Math.pow(t-1,2)}};
let scItems=null,scRaf=0;
function initScrolly(){
 const sec=view.querySelector('.scrolly');if(!sec){scItems=null;return}
 const els=[...sec.querySelectorAll('[data-s]')].map(el=>({el,s:+el.dataset.s,e:+el.dataset.e,pop:el.classList.contains('sc-pop'),last:-1}));
 const lives=[...sec.querySelectorAll('[data-on]')].map(el=>({el,on:+el.dataset.on}));
 scItems={sec,els,lives,steps:[...sec.querySelectorAll('.sc-steps li')],bar:sec.querySelector('.sc-bar i'),lastStep:-1};
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){sec.classList.add('sc-static');els.forEach(o=>o.el.style.setProperty('--t',1));lives.forEach(o=>o.el.classList.add('on'));scItems.steps.forEach(li=>li.classList.add('done'));scItems=null;return}
 updateScrolly();
}
function updateScrolly(){scRaf=0;const S=scItems;if(!S||!S.sec.isConnected)return;
 const r=S.sec.getBoundingClientRect(),vh=view.clientHeight,span=r.height-vh;if(r.bottom<-200||r.top>vh+200)return;
 const p=Math.min(1,Math.max(0,-r.top/Math.max(1,span)));
 for(const o of S.els){let t=Math.min(1,Math.max(0,(p-o.s)/((o.e-o.s)||1)));t=o.pop?easeSc.back(t):easeSc.out(t);t=Math.round(t*1000)/1000;if(t!==o.last){o.last=t;o.el.style.setProperty('--t',t)}}
 for(const o of S.lives)o.el.classList.toggle('on',p>=o.on);
 const n=S.steps.length,i=Math.min(n-1,Math.floor(p*n*.999));
 if(i!==S.lastStep){S.lastStep=i;S.steps.forEach((li,k)=>{li.classList.toggle('active',k===i);li.classList.toggle('done',k<i)})}
 if(S.bar)S.bar.style.transform=`scaleX(${p})`;
}
view.addEventListener('scroll',()=>{if(scItems&&!scRaf)scRaf=requestAnimationFrame(updateScrolly)},{passive:true});
addEventListener('resize',()=>{if(scItems&&!scRaf)scRaf=requestAnimationFrame(updateScrolly)});

