function avatar(id,k){const a=TEAM_PHOTOS[id];return a&&a[k]?`<img class="fam-ava" src="${a[k]}" alt="" width="72" height="72">`:''}


function teamRow(id){const ph=TEAM_PHOTOS[id];if(!ph)return '';
 const card=(k,i)=>{const [n,aka,role,tel]=TEAM_ROLES[k];
  return `<figure class="tm tm-${k}" style="--i:${i}"><div class="tm-frame"><img src="${ph[k]}" alt="${n} (${aka.slice(4)}), ${role}" loading="lazy" decoding="async">
   <span class="tm-tag">${(TEAM_TAGS[id]||TEAM_TAGS.arch)[i]}</span><i class="tm-c tl"></i><i class="tm-c tr"></i><i class="tm-c bl"></i><i class="tm-c br"></i><b class="tm-sticker">${(TEAM_STICK[id]||TEAM_STICK.kids)[i]}</b></div>
   <figcaption><small>${role}</small><strong>${n} <em>${aka}</em></strong><a href="tel:+91${tel}">${tel}</a></figcaption></figure>`};
 return `<div class="team" aria-label="The joint family">${card('des',0)}${card('dev',1)}</div>`}

function openWorld(id,event){
 lastOpener=(document.activeElement&&document.activeElement!==document.body)?document.activeElement:null;
 const w=WORLDS.find(x=>x.id===id)||WORLDS[0];currentWorld=id;
 const x=event&&Number.isFinite(event.clientX)?event.clientX:window.innerWidth/2;
 const y=event&&Number.isFinite(event.clientY)?event.clientY:window.innerHeight/2;
 view.style.setProperty('--cx',x+'px');view.style.setProperty('--cy',y+'px');document.documentElement.style.setProperty('--cursor',({modern:'#5b4ff5',elegant:'#b89458',hospital:'#0b95a6',salon:'#d4607c',illus:'#e76f51',mandala:'#c8391f',interior:'#66765a',arch:'#8bbcff',funny:'#ff5d8f',kids:'#ff7a1a',auto:'#e10600',future:'#00e5ff'})[id]||'#a78bfa');view.className='open theme-'+id;view.setAttribute('aria-hidden','false');
 view.innerHTML=worldPage(w,id);prepareLabels();initScrolly();
 view.scrollTop=0;document.body.style.overflow='hidden';mobileOn=false;observeLab();const uni=document.getElementById('universe');if(uni)uni.inert=true;const firstBtn=view.querySelector('.worldnav button');if(firstBtn)firstBtn.focus({preventScroll:true});setTimeout(()=>{view.classList.add('ready')},500);
 dispatchEvent(new CustomEvent('devocrat:world',{detail:{open:true,id}}));
}
function closeWorld(){view.className='';document.body.classList.remove('overlay-open');view.setAttribute('aria-hidden','true');document.body.style.overflow='';if(labObserver){labObserver.disconnect();labObserver=null}['desktopPreview','mobilePreview'].forEach(i=>{const f=document.getElementById(i);if(f){f.removeAttribute('srcdoc');f.src='about:blank'}});toggleFamily(false);if(lastOpener&&lastOpener.focus){try{lastOpener.focus({preventScroll:true})}catch(_){}}lastOpener=null;dispatchEvent(new CustomEvent('devocrat:world',{detail:{open:false}}));}
function selectApp(id){currentApp=id;mobileOn=false;view.querySelectorAll('.picker .project').forEach(b=>{const on=b.dataset.app===id;b.classList.toggle('active',on);b.setAttribute('aria-selected',on)});loadApp(id)}
function previewPlaceholder(){return '<!DOCTYPE html><meta name="viewport" content="width=device-width,initial-scale=1"><body style="margin:0;height:100vh;display:grid;place-items:center;background:#0d0e16;color:#e8e4d6;font:14px/1.5 system-ui,sans-serif;text-align:center;padding:20px;box-sizing:border-box"><div><p style="margin:0 0 14px">The 3D studio is heavy to run twice.<br>Load the phone preview when you need it.</p><button onclick="parent.postMessage(\'devocrat-load-mobile\',\'*\')" style="padding:10px 16px;border:1px solid #d1a92a;background:transparent;color:#f5e9c7;border-radius:4px;font:inherit;cursor:pointer">Load phone preview</button></div></body>'}
function setFrame(f,id){f.removeAttribute('srcdoc');f.src='apps/'+id+'.html'}
function loadApp(id){if(!appMeta.some(a=>a.id===id))return;const d=document.getElementById('desktopPreview'),m=document.getElementById('mobilePreview');if(d)setFrame(d,id);if(m){if(id==='interior'&&!mobileOn){m.removeAttribute('src');m.srcdoc=previewPlaceholder()}else setFrame(m,id)}}
function observeLab(){if(labObserver){labObserver.disconnect();labObserver=null}const lab=document.getElementById('lab');if(!lab)return;if(!('IntersectionObserver' in window)){loadApp(currentApp);return}labObserver=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)){loadApp(currentApp);if(labObserver){labObserver.disconnect();labObserver=null}}},{rootMargin:'300px'});labObserver.observe(lab);}
addEventListener('message',e=>{if(e.data!=='devocrat-load-mobile')return;const m=document.getElementById('mobilePreview');if(m&&e.source===m.contentWindow){mobileOn=true;setFrame(m,currentApp)}});
function reloadPreviews(){loadApp(currentApp)}
/* Previews are same-origin documents: hide their system cursor and drive the custom cursor from inside them. */
function hookFrame(f){try{const d=f.contentDocument;if(!d||d.__devocratCursor)return;d.__devocratCursor=1;
 const st=d.createElement('style');st.textContent='@media (hover:hover) and (pointer:fine){html,body,*,*::before,*::after{cursor:none!important}}';(d.head||d.documentElement).appendChild(st);
 const c=document.getElementById('cursorCore'),sel='a,button,input,select,textarea,label,summary,[role=button],[onclick]';
 d.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;const r=f.getBoundingClientRect();c.style.left=(r.left+e.clientX)+'px';c.style.top=(r.top+e.clientY)+'px'},{passive:true});
 d.addEventListener('pointerover',e=>document.body.classList.toggle('cursor-hover',!!(e.target.closest&&e.target.closest(sel))));
}catch(_){}}
function toggleFamily(force){const p=document.getElementById('familyPanel');if(!p)return;const open=force===undefined?!p.classList.contains('open'):force;if(open===p.classList.contains('open'))return;
 p.classList.toggle('open',open);document.body.classList.toggle('overlay-open',open);view.querySelector('.family-scrim')?.classList.toggle('open',open);const b=view.querySelector('.familybtn');if(b)b.setAttribute('aria-expanded',open);
 if(open)p.querySelector('.closefamily')?.focus({preventScroll:true});else b?.focus({preventScroll:true});}

/* Style-aware cursor, hover response and tap/click graphics. */
const core=document.getElementById('cursorCore'),fx=document.getElementById('fx');let mx=-100,my=-100;
document.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){mx=e.clientX;my=e.clientY;core.style.left=mx+'px';core.style.top=my+'px';}});
document.addEventListener('pointerover',e=>{if(e.target.closest('button,a,.world,.project,select'))document.body.classList.add('cursor-hover')});
document.addEventListener('pointerout',e=>{if(e.target.closest('button,a,.world,.project,select'))document.body.classList.remove('cursor-hover')});
function styleGlyph(){const map={modern:['✦','●','＋'],elegant:['✧','·','◇'],hospital:['＋','✚','○'],salon:['♡','✿','✧'],illus:['✎','✳','✦'],mandala:['✺','❋','✧'],interior:['◇','⌂','✧'],arch:['＋','⌗','□'],funny:['✦','★','!'],kids:['●','✿','★'],auto:['╱','⚡','✦'],future:['⌁','◇','＋']};const arr=map[currentWorld]||map.future;return arr[Math.floor(Math.random()*arr.length)]}
function burst(x,y,touch){const glyph=document.body.dataset.activeWorld==='landing'?'✦':styleGlyph(),el=document.createElement('span');el.className='fxbit';el.textContent=glyph;el.style.left=x+'px';el.style.top=y+'px';el.style.color=getComputedStyle(document.body).getPropertyValue('--cursor')||'#a78bfa';el.style.fontSize=(touch?30:20)+'px';el.style.setProperty('--dx',(Math.random()*90-45)+'px');el.style.setProperty('--dy',(Math.random()*-90-12)+'px');fx.appendChild(el);setTimeout(()=>el.remove(),800);
 const ring=document.createElement('span');ring.style.cssText=`position:absolute;left:${x}px;top:${y}px;width:12px;height:12px;border:1px solid var(--cursor);border-radius:${currentWorld==='arch'||currentWorld==='future'?'0':'50%'};transform:translate(-50%,-50%);animation:ring .55s ease-out forwards;`;fx.appendChild(ring);setTimeout(()=>ring.remove(),600);}
const ringStyle=document.createElement('style');ringStyle.textContent='@keyframes ring{to{width:76px;height:76px;opacity:0;transform:translate(-50%,-50%) rotate(45deg)}}';document.head.appendChild(ringStyle);
document.addEventListener('pointerdown',e=>{if(e.target.closest('iframe'))return;burst(e.clientX,e.clientY,e.pointerType!=='mouse');if(e.pointerType==='mouse'){core.animate([{transform:'translate(-50%,-50%) scale(1.7)'},{transform:'translate(-50%,-50%) scale(1)'}],{duration:180})}});
document.addEventListener('keydown',e=>{if(e.key!=='Escape'||!view.classList.contains('open'))return;if(document.getElementById('familyPanel')?.classList.contains('open'))toggleFamily(false);else closeWorld()});

/* Robust navigation + immersive action feedback */
(function(){
 const worldCursor={modern:'✦',elegant:'◇',hospital:'＋',salon:'♡',illus:'✎',mandala:'✺',interior:'⌂',arch:'⌗',funny:'★',kids:'✿',auto:'⚡',future:'⌁'};
 const style=document.createElement('style');style.textContent='#cursorCore:after{content:"";display:block;position:absolute;inset:3px;background:var(--cursor);border-radius:inherit}';document.head.appendChild(style);
 const originalOpen=window.openWorld;
 if(typeof originalOpen==='function'){window.openWorld=function(id,event){originalOpen(id,event);document.documentElement.dataset.world=id;const c=document.getElementById('cursorCore');if(c){c.style.borderRadius=({arch:'0',future:'0',auto:'2px',kids:'35%',funny:'8px'})[id]||'50%';c.style.width=({mandala:'26px',interior:'22px',hospital:'18px',auto:'12px',future:'24px'})[id]||'18px';c.dataset.glyph=worldCursor[id]||'✦';}}}
 // Fix nav buttons even if a world overlay was previously opened/closed.
 document.querySelectorAll('.topbar button').forEach(b=>b.addEventListener('click',e=>{const txt=b.textContent.toLowerCase();if(txt.includes('explore')){e.preventDefault();if(document.getElementById('worldView').classList.contains('open'))closeWorld();document.getElementById('worlds')?.scrollIntoView({behavior:'smooth',block:'start'});}else if(txt.includes('meet')){e.preventDefault();if(document.getElementById('worldView').classList.contains('open'))closeWorld();document.getElementById('people')?.scrollIntoView({behavior:'smooth',block:'start'});}}));
})();
